import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { sha256 } from '@noble/hashes/sha256';
import { bytesToHex, utf8ToBytes } from '@noble/hashes/utils';
import { leaf, build, proof, verify, toRef, toDigest, canonical } from './tree.js';

// Generated by `forge test --match-contract Vectors`. The contract decides the
// format; this file proves the SDK agrees with it.
const v = JSON.parse(readFileSync(new URL('./vectors.json', import.meta.url)));

test('leaf format matches the contract', () => {
  for (let i = 0; i < v.payments.length; i++) {
    assert.equal(leaf(v.payments[i], v.responses[i]), v.leaves[i], `leaf ${i}`);
  }
});

test('pair hashing matches the contract', () => {
  // The proof the contract built verifies under this file's hashPair.
  assert.ok(verify(v.proof0, v.root, v.leaves[0]));
});

test('a proof this file builds verifies against the root this file builds', () => {
  const tree = build(v.leaves);
  for (const l of v.leaves) {
    assert.ok(verify(proof(tree, l), tree.root, l));
  }
});

test('an odd number of deliveries still proves', () => {
  const leaves = ['a', 'b', 'c', 'd', 'e'].map((s, i) =>
    leaf(`0x${(i + 1).toString(16).padStart(64, '0')}`, `0x${s.charCodeAt(0).toString(16).padStart(64, '0')}`)
  );
  const tree = build(leaves);
  for (const l of leaves) {
    assert.ok(verify(proof(tree, l), tree.root, l), 'odd tree');
  }
});

test('a single delivery is its own root', () => {
  const only = leaf(`0x${'11'.repeat(32)}`, `0x${'22'.repeat(32)}`);
  const tree = build([only]);
  assert.equal(tree.root, only);
  assert.deepEqual(proof(tree, only), []);
});

test('an empty epoch has no root', () => {
  assert.throws(() => build([]));
});

test('a leaf not in the tree has no proof', () => {
  const tree = build(v.leaves);
  assert.throws(() => proof(tree, `0x${'ff'.repeat(32)}`));
});

// draft-etcheverry-action-ref-03, Appendix A.1. An action_ref must go in as the
// ref unchanged, so its issuer can recompute it and find the same bytes on chain.
test('an action_ref is the ref, byte for byte', () => {
  const preimage = {
    timestamp: '2025-05-18T11:40:31.000Z',
    scope: 'BTC',
    agent_id: 'nexus-agent-xa12.onrender.com',
    action_type: 'oracle.signal',
  };
  assert.equal(
    canonical(preimage),
    '{"action_type":"oracle.signal","agent_id":"nexus-agent-xa12.onrender.com","scope":"BTC","timestamp":"2025-05-18T11:40:31.000Z"}'
  );
  const actionRef = bytesToHex(sha256(utf8ToBytes(canonical(preimage))));
  assert.equal(actionRef, 'fdd7f810499f06be24355ca8e2bfb8c4b965cc80c838f41fa074683443d89f5a');
  assert.equal(toRef(actionRef), `0x${actionRef}`);
});

test('a 0x id passes through, lower cased', () => {
  const id = `0x${'AB'.repeat(32)}`;
  assert.equal(toRef(id), id.toLowerCase());
  assert.equal(toDigest(id), id.toLowerCase());
});

test('a UUID becomes a ref, and the same UUID always the same one', () => {
  const uuid = '7f9c2ba4-e88f-4a3d-9b1c-2f0e5d6a8c11';
  assert.match(toRef(uuid), /^0x[0-9a-f]{64}$/);
  assert.equal(toRef(uuid), toRef(uuid));
  assert.notEqual(toRef(uuid), toRef(uuid.toUpperCase()));
});

test('an envelope digests the same whatever order its keys arrive in', () => {
  const a = { evidence_id: 'x', evidence_data: { b: 2, a: 1 }, signature: 'ed25519:s' };
  const b = { signature: 'ed25519:s', evidence_data: { a: 1, b: 2 }, evidence_id: 'x' };
  assert.equal(toDigest(a), toDigest(b));
  assert.notEqual(toDigest(a), toDigest({ ...a, signature: 'ed25519:t' }));
});

test('bytes and the same text digest the same', () => {
  assert.equal(toDigest(utf8ToBytes('delivered')), toDigest('delivered'));
});

test('a converted pair seals and proves like any other', () => {
  const leaves = [
    leaf(toRef('fdd7f810499f06be24355ca8e2bfb8c4b965cc80c838f41fa074683443d89f5a'), toDigest({ ok: true })),
    leaf(toRef('7f9c2ba4-e88f-4a3d-9b1c-2f0e5d6a8c11'), toDigest('response body')),
    leaf(toRef(`0x${'cd'.repeat(32)}`), toDigest(`0x${'ef'.repeat(32)}`)),
  ];
  const tree = build(leaves);
  for (const l of leaves) assert.ok(verify(proof(tree, l), tree.root, l));
});

test('nothing that is not evidence gets a digest', () => {
  assert.throws(() => toDigest(undefined));
  assert.throws(() => toDigest(42));
  assert.throws(() => toRef(''));
  assert.throws(() => canonical({ n: NaN }));
});
